const now   = new Date();
const day   = now.getDay();
const date  = now.getDate();
const month = now.getMonth();

function weekOfMonth(d, targetDay) {
  let count = 0;
  for (let i = 1; i <= d; i++) {
    const wd = new Date(now.getFullYear(), month, i).getDay();
    if (wd === targetDay) count++;
  }
  return count;
}

