// 1. Get installed plugins
let plugins = [];
try {
  const r = await fetch(WP_URL + '/wp-json/wp/v2/plugins', { headers: H });
  if (r.ok) plugins = await r.json();
} catch(e) {}

// 2. Get WP core version
let wpVersion = 'desconocida';
try {
  const r = await fetch(WP_URL + '/wp-json/', { headers: H });
  if (r.ok) { const d = await r.json(); wpVersion = d.version || 'desconocida'; }
} catch(e) {}

// 3. Check latest WP core
let wpLatest = wpVersion;
try {
  const r = await fetch('https://api.wordpress.org/core/version-check/1.7/');
  if (r.ok) { const d = await r.json(); wpLatest = d.offers?.[0]?.version || wpVersion; }
} catch(e) {}

// 4. Check each active plugin against WP.org
const pluginUpdates = [];
const upToDate = [];
for (const plugin of plugins) {
  if (plugin.status !== 'active') continue;
  const slug = (plugin.plugin || '').split('/')[0];
  if (!slug) continue;
  try {
    const r = await fetch('https://api.wordpress.org/plugins/info/1.0/' + slug + '.json');
    if (r.ok) {
      const info = await r.json();
      if (info.version && info.version !== plugin.version) {
        pluginUpdates.push({ name: plugin.name, slug, current: plugin.version, latest: info.version });
      } else {
        upToDate.push(plugin.name);
      }
    }
  } catch(e) {}
}

const coreNeedsUpdate = wpVersion !== wpLatest;
const totalUpdates = pluginUpdates.length + (coreNeedsUpdate ? 1 : 0);

// 5. Check UpdraftPlus
let hasUpdraftPlus = false;
try {
  const r = await fetch(WP_URL + '/wp-json/updraftplus/v1/', { headers: H });
  hasUpdraftPlus = r.ok;
} catch(e) {}

// 6. Trigger backup if available
let backupTriggered = false;
if (hasUpdraftPlus && totalUpdates > 0) {
  try {
    const r = await fetch(WP_URL + '/wp-json/updraftplus/v1/backup', {
      method: 'POST', headers: H, body: JSON.stringify({})
    });
    backupTriggered = r.ok;
  } catch(e) {}
}

const summary = totalUpdates === 0
  ? '✅ Todo actualizado — WordPress ' + wpVersion + ', todos los plugins al día'
  : '⚠️ ' + totalUpdates + ' actualización(es) pendiente(s)';

return [{ json: {
  wpVersion, wpLatest, coreNeedsUpdate,
  pluginUpdates, upToDate, totalUpdates,
  backupTriggered, hasUpdraftPlus,
  summary
}}];

