  const results = (data.organic_results || []).map((r, i) => ({
    position: i + 1,
    title: r.title || '',
    link: r.link || '',
    snippet: r.snippet || ''
  }));
  const cePosition = results.find(r => r.link.includes('cratingexpress.com'))?.position || null;
  return { topResults: results.slice(0, 5), cePosition };
}

